 function legacyClaimCard(c,r,q){const checked=r.checking?.state==='complete',fact=q.kind==='fact',hasEvidence=(q.evidence||[]).some(e=>publicURL(e.url)&&e.quote&&e.hash),verdict=fact&&(!checked||!hasEvidence)?'unconfirmed':q.verdict||'unconfirmed',use=fact&&(!checked||!hasEvidence)?'held':q.use||'held',decision=r.decisions?.[q.id],picked=typeof decision==='string'?decision:decision?.decision,sourceTitle=(c.live.flow?.materials||[]).find(m=>m.sourceId===q.sourceId)?.title||'Source material';return `<section class="flow-claim"><div class="flow-row"><span class="flow-badge">${esc(q.kind||'fact')}</span><span class="flow-badge">${esc(verdict)}</span><span class="small">${esc(use)}</span></div><p>${esc(q.statement)}</p>${q.qualification?'<p class="small">Use with: '+esc(q.qualification)+'</p>':''}<section class="flow-details" data-disclosure="claim:${esc(q.id)}"><h3>Source words${locatorLabel(q.locator)?' · '+esc(locatorLabel(q.locator)):''} and evidence${q.evidence?.length?' ('+q.evidence.length+')':''}</h3><blockquote>${esc(q.quote)}</blockquote><p>${esc(sourceTitle)}${locatorDetail(q.locator)?' · '+esc(locatorDetail(q.locator)):''}</p><section class="flow-details"><h3>Source identifier</h3><p>${esc(q.sourceId)}</p></section><p>${esc(q.reason||'')}</p>${evidenceLinks(q.evidence)}${!q.evidence?.length?'<p>No public evidence captured for this line.</p>':''}</section>${q.flag?`<div class="flow-flag"><p>${esc(q.flag.reason)}</p><p class="small">Suggested: ${esc(q.flag.suggestion)}${q.flag.action?' · '+esc(q.flag.action):''}</p>${checked?`<div class="flow-row">${[['suggested','Suggested'],['as-said','As said'],['cut','Cut'],['my-words','My words']].map(([d,label])=>`<button class="flow-action" data-flow-action="decide:${enc(q.id)}:${d}" aria-pressed="${picked===d}" data-blocked="${!!r.stale||c.live.flow?.researchAvailable===false}" ${c.live.flow?.researchAvailable===false?'disabled':''}>${label}</button>`).join('')}</div><section class="flow-details" data-disclosure="words:${esc(q.id)}"><h3>Write your version</h3>${field(c,'words:'+q.id,'Your words','New narration or wording — the source quote stays intact.')}${button('decide:'+enc(q.id)+':my-words','Save my words',!!r.stale)}</section>${picked?'<p class="small">Saved choice: '+esc(picked)+(decision?.words?' · '+esc(decision.words):'')+'</p>':'<p class="small">Awaiting your decision. No suggestion is accepted automatically.</p>'}`:'<p class="small">Line decisions open after the public check finishes. Suggested wording is read-only for now.</p>'}</div>`:''}</section>`;}
