 if(stage===3){const selected=c.local.selected;const match=r&&r.question===((c.local.drafts.question||'').trim()||'Check and deepen this source, develop a reusable brief and informed directions.')&&JSON.stringify([...r.sourceIds||[]].sort())===JSON.stringify([...selected].sort());body=`${!r?.body?(retainedResearch(c)||'<h2>Research and understand</h2>'):'<h2>Research and understand</h2>'}<section class="flow-details" data-disclosure="research-inputs" ${!r?.body&&!WORKFLOW_RECORDS[c.id]?'open':''}><h3>Research sources and question</h3><p>Source analysis reads only selected material. It remains unchecked until public evidence is captured.</p><div class="flow-sources">${ms.filter(m=>!['audio','video','image'].includes(m.kind)).map(m=>`<label class="flow-check"><input type="checkbox" data-source="${esc(m.sourceId)}" ${selected.includes(m.sourceId)?'checked':''}>${esc(shownTitle(m))} <span class="small">${m.reviewed||c.local.reviews[m.sourceId]===m.hash?'Ready for use':'Needs source review'}</span></label>`).join('')}</div>${field(c,'question','What do you want to understand? (optional)','Ask what these sources can help answer.')}<div class="flow-row">${button('analyze','Research these sources',!selected.length||analysisActive(c))}<span class="small">${esc(r?.execution?.state||r?.status||'Uses the current source revision. Your question is optional.')}</span></div></section>${r&&!match?'<p class="small">Source selection or question changed. Research these sources again.</p>':''}${r?.stale?'<p class="flow-error">Source revision changed. Research its current version before checking or deciding.</p>':''}${r?.error?'<p class="flow-error">'+esc(r.error)+'</p>':''}${r?.error&&['failed','needs-attention'].includes(r.execution?.state||r.status)?`<section class="flow-details" data-disclosure="research-recovery"><h3>Recover saved research</h3><p>Inspect a returned model artifact again after validation is corrected. This uses the saved result and does not generate new research.</p>${button('reinspect','Inspect saved research',!!r.stale)}</section>`:''}${r?.body?`<div class="flow-check-public"><div class="flow-row">${button('check',r.checking?.state==='running'?'Checking…':r.checking?.state==='complete'?'Check again':'Check public facts',!!r.stale||r.checking?.state==='running'||!match)}<span class="small">${esc(r.checking?.state||'No external check')}</span></div><p class="small">Sends public fact queries to a search provider and captures public evidence. Full sources are never sent automatically; this does not start private jobs.</p>${r.checking?.error?'<p class="flow-error">'+esc(shownError(r.checking.error))+'</p>':''}</div>`:''}${researchResult(c,r)}${r?`<section class="flow-details" data-disclosure="request"><h3>Captured source IDs and request</h3><p>${esc(r.requestId)}<br>Context: ${esc(r.contextHash)}</p>${(r.sourceIds||[]).map(id=>'<p>'+esc(id)+'</p>').join('')}</section>`:''}`}
 if(stage===4){const e=r?.editorial,map=e?.map;body=`<h2>${!r?.body&&retainedMap(c)?'Your recorded direction':'Choose the direction'}</h2>${map?`<div class="flow-map-verdict"><strong>${esc(map.verdict==='one'?'One piece':map.verdict==='multiple'?'Several pieces':map.verdict)}</strong><p>${esc(map.why)}</p></div>`:r?.body?'<p class="small">Directions from source analysis · unreviewed · no external check.</p>':(retainedMap(c)||'<p>Read and review your sources, then research them in stage 3.</p>')}${r?.stale?'<p class="flow-error">The source changed. Analyze its current revision before choosing.</p>':''}<div class="flow-directions">${(f?.directions||[]).slice(0,3).map((d,i)=>`<section class="flow-direction"><span class="small">${i===0?'Best fit · ':''}Direction ${i+1}${f.choice?.directionIndex===i?' · chosen':''}</span><h3>${esc(d.title)}</h3><div class="flow-prose">${safeProse(d.angle)}${safeProse(d.reason||d.recommendationWhy)}</div>${d.quotes?.length?`<section class="flow-details" data-disclosure="direction:${i}"><h3>Exact source passages</h3>${d.quotes.map(q=>'<blockquote>'+esc(q.quote)+'<small>'+esc(q.sourceId)+(q.locator?' · '+esc(q.locator):'')+'</small></blockquote>').join('')}</section>`:''}${button('pick:'+i,f.choice?.directionIndex===i?'Chosen':'Choose',!!r?.stale||!!f.choice&&!f.choice.stale&&!f.choice.needsReview)}</section>`).join('')}</div>${f?.directions?.length?field(c,'choiceNote','Your reason or adjustment','Optional',true):''}${f?.choice?'<p class="small">Saved direction'+(f.choice.date||f.choice.createdAt?' · '+esc(f.choice.date||f.choice.createdAt):'')+(f.choice.note?' · '+esc(f.choice.note):'')+'</p>':''}${map?.titles?.length?`<section class="flow-titles"><h3>Title possibilities</h3><p class="small">Suggestions for your chosen direction.</p><ol>${map.titles.map(t=>'<li>'+esc(t)+'</li>').join('')}</ol></section>`:''}${r?.body?reusableBrief(e,r):''}`}
 if(stage===3&&c.live.readOnlyPickup&&r?.body)body='<h2>Research</h2>'+researchResult(c,r);
